 16 // Starts the server; resolves to { port, proc, stderr } once listening.
 17 function start(env, cwd) {
 18   return new Promise((resolve, reject) => {
 19     const proc = spawn(process.execPath, [SERVER], {
 20       cwd: cwd ?? tmpDir(),
 21       env: { ...process.env, PORT: '0', ...env },
 22     });
 23     let out = '';
 24     let err = '';
 25     proc.stdout.on('data', (d) => {
 26       out += d;
 27       const m = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/.exec(out);
 28       if (m) resolve({ port: Number(m[1]), proc, out: () => out });
 29     });
 30     proc.stderr.on('data', (d) => (err += d));
 31     proc.on('exit', (code) => reject(Object.assign(new Error('exited'), { code, stderr: err, stdout: out })));
 32   });
 33 }
 34 
 35 // Runs a server expected to fail at startup.
 36 function run(env, cwd) {
 37   return new Promise((resolve) => {
 38     const proc = spawn(process.execPath, [SERVER], { cwd: cwd ?? tmpDir(), env: { ...process.env, ...env } });
 39     let out = '';
 40     let err = '';
 41     proc.stdout.on('data', (d) => (out += d));
 42     proc.stderr.on('data', (d) => (err += d));
 43     proc.on('exit', (code) => resolve({ code, stdout: out, stderr: err }));
 44   });
 45 }
 46 
 47 function stop(proc) {
 48   return new Promise((resolve) => {
 49     if (proc.exitCode !== null) return resolve();
 50     proc.once('exit', resolve);
 51     proc.kill();
 52   });
 53 }
