 55 function req(port, method, target, { body, headers } = {}) {
 56   return new Promise((resolve, reject) => {
 57     const r = http.request({ host: '127.0.0.1', port, method, path: target, headers, agent: false }, (res) => {
 58       const chunks = [];
 59       res.on('data', (c) => chunks.push(c));
 60       res.on('end', () => {
 61         const text = Buffer.concat(chunks).toString('utf8');
 62         let json;
 63         try {
 64           json = text === '' ? undefined : JSON.parse(text);
 65         } catch {
 66           json = undefined;
 67         }
 68         resolve({ status: res.statusCode, headers: res.headers, text, json });
 69       });
 70     });
 71     r.on('error', reject);
 72     if (body !== undefined) r.write(body);
 73     r.end();
 74   });
 75 }
