 14 class Text {
 15   constructor(text) {
 16     this.textContent = text;
 17   }
 18 }
 19 
 20 class Element {
 21   constructor(tag) {
 22     this.tag = tag;
 23     this.children = [];
 24     this.listeners = {};
 25     this.value = '';
 26     this.type = '';
 27     this.disabled = false;
 28   }
 29   get textContent() {
 30     return this.children.map((c) => c.textContent).join('');
 31   }
 32   set textContent(text) {
 33     this.children = text === '' ? [] : [new Text(text)];
 34   }
 35   append(...nodes) {
 36     for (const n of nodes) this.children.push(typeof n === 'string' ? new Text(n) : n);
 37   }
 38   replaceChildren(...nodes) {
 39     this.children = [];
 40     this.append(...nodes);
 41   }
 42   addEventListener(type, fn) {
 43     (this.listeners[type] ??= []).push(fn);
 44   }
 45   dispatch(type) {
 46     const event = { defaultPrevented: false, preventDefault() { this.defaultPrevented = true; } };
 47     for (const fn of this.listeners[type] ?? []) fn(event);
 48     return event;
 49   }
 50 }
