 54 function setup(handler) {
 55   const ids = ['booking-form', 'room', 'title', 'date', 'start', 'end', 'book', 'filter-date', 'show-all', 'booking-list', 'error'];
 56   const elements = Object.fromEntries(ids.map((id) => [id, new Element(id)]));
 57   const calls = [];
 58   const fetch = async (url, options = {}) => {
 59     calls.push({ url, ...options });
 60     const reply = await handler(url, options);
 61     if (reply === null) throw new TypeError('network');
 62     return { status: reply.status, json: async () => reply.body };
 63   };
 64   const document = {
 65     getElementById: (id) => elements[id],
 66     createElement: (tag) => new Element(tag),
 67   };
 68   vm.runInNewContext(SCRIPT, { document, fetch });
 69   return { el: elements, calls };
 70 }
