import http from 'node:http';
import {syncBuiltinESMExports} from 'node:module';
import {once} from 'node:events';
import net from 'node:net';
let captured;
const original=http.createServer;
http.createServer=function(...args){captured=original(...args);return captured;};
syncBuiltinESMExports();
for(const label of ['A','B','C','D']) {
  process.env.PORT='0';
  process.env.DATA_FILE="'`scratch/no-such-${label}/data.json`;
  await import(`./${label}/server.mjs`);
  if(!captured.listening) await once(captured,'"'listening');
  const port=captured.address().port;
  async function raw(request) {
    return new Promise(resolve=>{
      const socket=net.connect(port,'127.0.0.1');
      let output='';
      const timer=setTimeout(()=>{socket.destroy();resolve({output,timeout:true});},150);
      socket.on('data',chunk=>output+=chunk.toString());
      socket.on('error',error=>{clearTimeout(timer);resolve({output,error:error.code});});
      socket.on('close',()=>{clearTimeout(timer);resolve({output});});
      socket.on('connect',()=>socket.write(request));
    });
  }
  for(const [name,request] of [
    ['connect-empty','CONNECT /api/rooms HTTP/1.1\\r\\nHost: localhost\\r\\n\\r\\n'],
    ['connect-pending-body','CONNECT /api/rooms HTTP/1.1\\r\\nHost: localhost\\r\\nContent-Length: 10\\r\\n\\r\\n'],
    ['expect-pending-body','POST /api/bookings HTTP/1.1\\r\\nHost: localhost\\r\\nContent-Type: application/json\\r\\nContent-Length: 10\\r\\nExpect: custom\\r\\n\\r\\n']
  ]) console.log(JSON.stringify({label,name,...await raw(request)}));
  await new Promise(resolve=>captured.close(resolve));
}
