  53  * Resolves { code, signal, stdout, stderr }. Fails if it does not exit in time.
  54  */
  55 export async function runUntilExit({ env = {}, cwd, timeoutMs = EXIT_TIMEOUT_MS } = {}) {
  56   const { child, output, closed } = spawnServer({ env, cwd });
  57   try {
  58     const { code, signal } = await withTimeout(closed, timeoutMs, 'server did not exit');
  59     return { code, signal, stdout: output.stdout, stderr: output.stderr };
  60   } finally {
  61     if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
  62   }
  63 }
