import http from 'node:http';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {syncBuiltinESMExports} from 'node:module';
import {once} from 'node:events';
import assert from 'node:assert/strict';
const disk=new Map();
let failWrite=false, writes=0, capture;
const realRead=fs.readFileSync, realReadAsync=fsp.readFile, create=http.createServer;
const key=p=>path.resolve(p instanceof URL?fileURLToPath(p):p);
fs.readFileSync=(p,options)=>disk.has(key(p))?(options?disk.get(key(p)):Buffer.from(disk.get(key(p)))):realRead(p,options);
fsp.readFile=async(p,options)=>disk.has(key(p))?(options?disk.get(key(p)):Buffer.from(disk.get(key(p)))):realReadAsync(p,options);
fsp.writeFile=async(p,text)=>{
  assert.ok(key(p).startsWith(path.resolve('scratch')+path.sep));
  await new Promise(r=>setImmediate(r));
  if(failWrite) throw Object.assign(new Error('simulated save failure'),{code:'EACCES'});
  disk.set(key(p),String(text)); writes++;
};
http.createServer=(...args)=>{const s=create(...args);capture(s);return s;};
syncBuiltinESMExports();
for(const label of ['A','B','C','D']) {
  let checks=0;
  async function boot(suffix) {
    const created=new Promise(resolve=>capture=resolve);
    process.env.PORT='0';process.env.DATA_FILE="'`scratch/${label}-virtual.json`;
    await import(`./${label}/server.mjs?probe=${suffix}`);
    const s=await created;if(!s.listening)await once(s,'"'listening');return s;
  }
  let server=await boot('initial');
  const sample={room:'Aurora',title:' Standup ',date:'2026-11-03',start:'09:00',end:'10:00'};
  async function request(method,target,body,contentType='application/json') {
    return new Promise((resolve,reject)=>{
      const req=http.request({host:'127.0.0.1',port:server.address().port,path:target,method,agent:false,headers:body===undefined?{}:{'Content-Type':contentType}},res=>{
        const chunks=[];res.on('data',c=>chunks.push(c));res.on('end',()=>{const raw=Buffer.concat(chunks).toString();resolve({status:res.statusCode,json:raw?JSON.parse(raw):null,headers:res.headers});});
      });req.on('error',reject);req.end(body);
    });
  }
  async function status(method,target,body,expected,type) {const r=await request(method,target,body, type);assert.equal(r.status,expected,"'`${label} ${method} ${target}`);checks++;return r;}
  const rooms=await status('"'GET','/api/rooms',undefined,200);assert.deepEqual(rooms.json,{rooms:['Aurora','Borealis','Cosmos']});
  for(const route of ['/api/./rooms','/api/%62ookings','/API/rooms','/api/bookings/','/api/bookings/1/'])await status('GET',route,undefined,404);
  await status('GET','/api/bookings/abc',undefined,405);
  for(const target of ['/api/bookings?date','/api/bookings?date=&date=2026-11-03','/api/bookings?date=2026-02-29'])await status('GET',target,undefined,400);
  await status('POST','/api/bookings','x'.repeat(10001),415,'text/plain');
  await status('POST','/api/bookings','x'.repeat(10001),413);
  for(const body of ['null','[]','true','\\ufeff{}','{}'])await status('POST','/api/bookings',body,400);
  failWrite=true;await status('POST','/api/bookings',JSON.stringify(sample),500);failWrite=false;
  assert.deepEqual((await request('GET','/api/bookings')).json,{bookings:[]});checks++;
  const first=await status('POST','/api/bookings',JSON.stringify(sample),201,' APPLICATION/JSON ; charset=utf-8');
  assert.equal(first.json.id,1);assert.equal(first.json.title,'Standup');
  await status('POST','/api/bookings',JSON.stringify({...sample,start:'10:00',end:'11:00'}),201);
  const clash=await status('POST','/api/bookings',JSON.stringify({...sample,start:'09:30',end:'10:30'}),409);
  assert.equal(clash.json.error,'room is already booked from 09:00 to 10:00');
  const concurrent=await Promise.all(Array.from({length:12},()=>request('POST','/api/bookings',JSON.stringify({...sample,date:'2026-11-04'}))));
  assert.equal(concurrent.filter(r=>r.status===201).length,1);assert.equal(concurrent.filter(r=>r.status===409).length,11);checks++;
  failWrite=true;await status('DELETE','/api/bookings/1',undefined,500);failWrite=false;
  assert.equal((await request('GET','/api/bookings')).json.bookings.length,3);checks++;
  await status('DELETE','/api/bookings/1',undefined,204);
  await new Promise(resolve=>server.close(resolve));
  server=await boot('restart');
  assert.equal((await request('GET','/api/bookings')).json.bookings.length,2);checks++;
  const next=await status('POST','/api/bookings',JSON.stringify({...sample,date:'2026-11-05'}),201);assert.equal(next.json.id,4);
  await new Promise(resolve=>server.close(resolve));
  console.log(JSON.stringify({label,checks,result:'PASS',storage:'in-memory filesystem stub; actual HTTP; no disk writes'}));
}
